+namespace BlazorApp.Services;
+
+public class NotificationItem
+{
+    public int Id { get; set; }
+    public string Message { get; set; } = string.Empty;
+    public DateTime Timestamp { get; set; }
+}
+
+public class NotificationService
+{
+    private int _nextId = 1;
+    private readonly Lock _lock = new();
+
+    private readonly string[] _sampleMessages =
+    [
+        "New comment on your pull request",
+        "Build succeeded for main branch",
+        "Deployment to production complete",
+        "New team member joined the project",
+        "Security alert: dependency update available",
+        "Code review requested",
+        "Issue #42 was closed",
+        "Release v2.1.0 published"
+    ];
+
+    public Task<List<NotificationItem>> GetInitialNotificationsAsync()
+    {
+        lock (_lock)
+        {
+            var notifications = new List<NotificationItem>();
+            for (int i = 0; i < 3; i++)
+            {
+                notifications.Add(new NotificationItem
+                {
+                    Id = _nextId++,
+                    Message = _sampleMessages[i],
+                    Timestamp = DateTime.UtcNow.AddMinutes(-10 + i)
+                });
+            }
+            return Task.FromResult(notifications);
+        }
+    }
+
+    public Task<List<NotificationItem>> CheckForNewNotificationsAsync(int lastSeenId)
+    {
+        lock (_lock)
+        {
+            var newNotifications = new List<NotificationItem>();
+
+            // ~30% chance of a new notification each poll
+            if (Random.Shared.Next(100) < 30)
+            {
+                var msg = _sampleMessages[Random.Shared.Next(_sampleMessages.Length)];
+                newNotifications.Add(new NotificationItem
+                {
+                    Id = _nextId++,
+                    Message = msg,
+                    Timestamp = DateTime.UtcNow
+                });
+            }
+
+            return Task.FromResult(newNotifications);
+        }
+    }
+}
